import type { Metadata } from "next";import Image from 'next/image';import {notFound} from "next/navigation";import Link from "next/link";import {BadgeCheck,CalendarDays,MapPin,Star,ArrowLeft,MessageCircle,ArrowRight} from "lucide-react";import {photo} from "@/lib/data";import {getVendor, listVendors} from "@/services/vendors";import {money} from "@/lib/utils";import {VendorCard} from "@/components/vendor-card";import {FavoriteButton} from "@/components/favorite-button";import { prisma } from "@/lib/prisma";import { getCurrentUser } from "@/lib/auth/session";
export async function generateMetadata({params}:{params:Promise<{id:string}>}):Promise<Metadata>{const {id}=await params;const vendor=await getVendor(id);if(!vendor)return {title:"Vendor not found"};return {title:`${vendor.name} — ${vendor.category} in ${vendor.city}`,description:vendor.description,openGraph:{title:`${vendor.name} | WEDORA`,description:vendor.description,type:"website"}}}
export default async function VendorDetail({params}:{params:Promise<{id:string}>}){const {id}=await params;const v=await getVendor(id);if(!v)notFound();const allSimilar=await listVendors({category: v.category});const similar=allSimilar.filter(x=>x.id!==v.id).slice(0,3);const user=await getCurrentUser();let isFavorited=false;if(user?.couple){const fav=await prisma.favoriteVendor.findUnique({where:{coupleId_vendorId:{coupleId:user.couple.id,vendorId:v.id}}});if(fav)isFavorited=true;}return <main className="mx-auto max-w-[1320px] px-6 py-8"><Link className="flex items-center gap-2 text-xs text-[#817970]" href="/vendors"><ArrowLeft size={15}/>All vendors</Link><div className="mt-6 grid gap-3 overflow-hidden rounded-2xl md:h-[460px] md:grid-cols-3"><Image width={1400} height={900} sizes="(max-width: 768px) 100vw, 50vw" className="h-full min-h-64 w-full object-cover md:col-span-2" src={photo(v.image,1400)} alt={`${v.name} wedding portfolio`}/><div className="hidden grid-rows-2 gap-3 md:grid"><Image width={1400} height={900} sizes="(max-width: 768px) 100vw, 50vw" className="h-full w-full object-cover" src={photo("photo-1519225421980-715cb0215aed",700)} alt="Wedding portfolio detail"/><Image width={1400} height={900} sizes="(max-width: 768px) 100vw, 50vw" className="h-full w-full object-cover" src={photo("photo-1464366400600-7168b8af9bc3",700)} alt="Wedding table setting"/></div></div><div className="grid gap-10 py-10 lg:grid-cols-[1fr_360px]"><section><div className="flex items-center gap-2 text-xs uppercase tracking-[.18em] text-[#a6796f]">{v.category}{v.verified&&<><span>·</span><BadgeCheck size={15}/>Verified</>}</div><h1 className="serif mt-3 text-4xl md:text-5xl">{v.name}</h1><div className="mt-4 flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-[#817970]"><span className="flex items-center gap-1"><MapPin size={15}/>{v.area}, {v.city}</span><span className="flex items-center gap-1"><Star size={15} className="fill-[#ba9973] text-[#ba9973]"/><b className="text-[#302d29]">{v.rating}</b> ({v.reviews} reviews)</span></div><p className="mt-8 max-w-2xl leading-7 text-[#625d56]">{v.description} Based in {v.area}, serving couples across {v.city} and beyond. Our team brings thoughtful care and an eye for the details that make a celebration feel like yours.</p><div className="mt-8 border-y border-[#e9e4de] py-6"><h2 className="serif text-2xl">What makes us, us</h2><div className="mt-4 flex flex-wrap gap-2">{v.style.split(", ").map(s=><span key={s} className="rounded-full bg-[#f0ebe5] px-4 py-2 text-xs">{s}</span>)}</div></div><div className="mt-8"><h2 className="serif text-2xl">A glimpse of our work</h2><div className="mt-5 grid grid-cols-2 gap-3 md:grid-cols-3">{[v.image,"photo-1519225421980-715cb0215aed","photo-1464366400600-7168b8af9bc3"].map((im,i)=><Image width={1400} height={900} sizes="(max-width: 768px) 100vw, 50vw" key={i} className="aspect-square w-full rounded-xl object-cover" src={photo(im,650)} alt={`${v.name} portfolio ${i+1}`}/>)}</div></div></section><aside><div className="sticky top-24 rounded-2xl border border-[#e9e4de] bg-white p-6"><div className="text-xs text-[#817970]">Packages from</div><div className="serif mt-1 text-3xl">{money(v.price)}</div><p className="mt-2 text-xs text-[#817970]">Final pricing varies by date and details.</p><div className="my-5 border-t border-[#e9e4de]"/><div className="flex items-center gap-3 text-sm"><CalendarDays size={17} className="text-[#a6796f]"/>Ask about your date</div><Link href={`/dashboard/bookings/request?vendor=${v.id}`} className="mt-6 flex items-center justify-center gap-2 rounded-full bg-[#302d29] px-5 py-3.5 text-sm text-white">Request a booking <ArrowRight size={16}/></Link><Link href={`/dashboard/messages?vendor=${v.id}`} className="mt-3 flex items-center justify-center gap-2 rounded-full border border-[#e9e4de] px-5 py-3.5 text-sm"><MessageCircle size={16}/> Message vendor</Link><FavoriteButton id={v.id} name={v.name} inline initialSaved={isFavorited}/></div></aside></div>{similar.length>0&&<section className="border-t border-[#e9e4de] py-12"><div className="flex items-end justify-between"><h2 className="serif text-3xl">More to fall for</h2><Link href={`/vendors?category=${v.category}`} className="text-sm">View all {v.category}</Link></div><div className="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{similar.map(x=><VendorCard key={x.id} vendor={x}/>)}</div></section>}</main>}





